/// If `c` is a Unicode decimal-digit character (category Nd, per Python's
/// `unicodedata.decimal`), return its value 0-9. ASCII is fast-pathed.
pub fn unicode_digit(c: char) -> Option<u8> {
    if c.is_ascii_digit() {
        return Some(c as u8 - b'0');
    }
    let cp = c as u32;
    UNICODE_DIGITS
        .binary_search_by(|&(k, _)| k.cmp(&cp))
        .ok()
        .map(|i| UNICODE_DIGITS[i].1)
}


