/// Digit value of an isolated (non-decimal) numeric character, if any.
pub fn unicode_isolated_digit(c: char) -> Option<u8> {
    let cp = c as u32;
    UNICODE_ISOLATED_DIGITS
        .binary_search_by(|&(k, _)| k.cmp(&cp))
        .ok()
        .map(|i| UNICODE_ISOLATED_DIGITS[i].1)
}
